or .16s ease,transform .16s ease}.post-card:hover{border-color:var(--accent);transform:translateY(-1px)}.post-card__author{display:flex;align-items:center;gap:var(--space-2)}.author-link{color:var(--text);font-size:.92rem;font-weight:700;text-decoration:none}.author-link:hover{color:var(--accent);text-decoration:underline}.post-meta{margin:1px 0 0;color:var(--subtle);font-size:.8rem}.post-card__body{min-width:0}.post-title{color:var(--text);font-size:clamp(1.15rem,2vw,1.4rem);font-weight:760;line-height:1.35;text-decoration:none}.post-title:hover{color:var(--accent);text-decoration:underline;text-underline-offset:3px}.post-excerpt{display:-webkit-box;overflow:hidden;margin:var(--space-2) 0 0;color:var(--muted);line-height:1.65;-webkit-line-clamp:2;-webkit-box-orient:vertical}.post-taxonomy{display:flex;flex-wrap:wrap;gap:var(--space-1);margin-top:var(--space-3)}.taxonomy-link{padding:2px var(--space-2);border:1px solid var(--border);border-radius:999px;color:var(--muted);font-size:.8rem;text-decoration:none}.taxonomy-link:hover{border-color:var(--accent);color:var(--accent)}.post-card__footer{display:flex;flex-wrap:wrap;align-items:center;gap:var(--space-3);padding-top:var(--space-3);border-top:1px solid var(--border);color:var(--subtle);font-size:.82rem}.post-card__footer span{display:inline-flex;align-items:center;gap:5px}.read-link{display:inline-flex;align-items:center;gap:4px;margin-left:auto;color:var(--accent);font-weight:700;text-decoration:none}.read-link:hover{text-decoration:underline}.explore-aside{display:grid;gap:var(--space-3);position:sticky;top:var(--space-4)}.aside-card{padding:var(--space-4)}.aside-heading{display:flex;align-items:center;gap:var(--space-2);color:var(--accent)}.aside-heading h2{margin:0;color:var(--text);font-size:1rem}.topic-list{display:flex;flex-wrap:wrap;gap:var(--space-2);margin-top:var(--space-3)}.topic-list a{color:var(--muted);font-size:.9rem;text-decoration:none}.topic-list a:hover{color:var(--accent);text-decoration:underline}.creator-list{display:grid;gap:var(--space-3);margin-top:var(--space-3)}.creator{display:flex;align-items:center;gap:var(--space-2);color:var(--text);text-decoration:none}.creator:hover b{color:var(--accent);text-decoration:underline}.creator span{display:grid;min-width:0}.creator b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.9rem}.creator small{color:var(--subtle);font-size:.78rem}.aside-empty{margin:var(--space-3) 0 0;font-size:.9rem}.guide-card p{margin:var(--space-3) 0;font-size:.9rem}.pagination{display:flex;align-items:center;justify-content:center;gap:var(--space-3);margin-top:var(--space-5);color:var(--muted);font-size:.9rem}.empty{display:grid;justify-items:center;gap:var(--space-2);margin:var(--space-4) 0}.empty p{margin:0}.error-state{border-style:solid}@media(max-width:900px){.explore-layout{grid-template-columns:1fr}.explore-aside{position:static;grid-template-columns:repeat(2,minmax(0,1fr))}.guide-card{grid-column:1/-1}}@media(max-width:640px){.explore-header{align-items:start;flex-direction:column;margin-bottom:var(--space-5)}.search-row{grid-template-columns:1fr}.search-row .button{width:100%}.active-filter{align-items:start;flex-direction:column}.post-card{padding:var(--space-3)}.post-card__footer{gap:var(--space-2)}.read-link{width:100%;margin-left:0;margin-top:var(--space-1)}.explore-aside{grid-template-columns:1fr}}
</style>
